var registerActivitiesCommand = (program2) => {
  const activities = program2.command("activities").description("Manage UiPath Integration Service activities");
  activities.command("list").description("List activities for a connector").argument("<connector-key>", "Connector key (e.g., uipath-zoho-desk)").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--refresh", "Force re-fetch from API, ignoring cache").option("--triggers", "List trigger activities only").examples(ACTIVITIES_LIST_EXAMPLES).trackedAction(processContext, async (connectorKey, options) => {
    const isTriggerMode = options.triggers === true;
    const modeLabel = isTriggerMode ? "trigger" : "non-trigger";
    logger.info(`Listing ${modeLabel} activities for connector: ${connectorKey}${options.refresh ? " [refresh]" : ""}`);
    let data = null;
    if (!options.refresh) {
      data = await readActivities(connectorKey, options.tenant);
      if (data)
        logger.info(`Loaded ${data.length} activities from cache`);
    }
    if (!data) {
      const [error, api] = await catchError(createApiClient(ElementsApi, {
        tenant: options.tenant
      }));
      if (error) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Error creating API client",
          Instructions: error.message
        });
        processContext.exit(1);
        return;
      }
      const [fetchError, fetched] = await catchError(api.getActivities({ elementKey: connectorKey }));
      if (fetchError) {
        const msg = await extractErrorMessage(fetchError);
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: `Error listing activities for connector '${connectorKey}'`,
          Instructions: msg
        });
        processContext.exit(1);
        return;
      }
      data = fetched;
      if (data && data.length > 0)
        await writeActivities(connectorKey, data, options.tenant);
    }
    const filtered = data ? filterByTriggerMode(data, isTriggerMode) : [];
    OutputFormatter.emitList(isTriggerMode ? "TriggerActivityList" : "ActivityList", formatActivityList(filtered), {
      emptyInstructions: !data || data.length === 0 ? `No activities found for connector '${connectorKey}'. Check that the connector key is correct.` : isTriggerMode ? `No trigger activities found for connector '${connectorKey}'. This connector has no trigger activities.` : `No non-trigger activities found for connector '${connectorKey}'. All activities are triggers — use --triggers to list them.`
    });
  });
};

// src/helpers/connections.ts
function mergeConnectionDetails(connections, detailedConnections) {
  const detailsById = new Map(detailedConnections.filter((connection) => typeof connection.id === "string").map((connection) => [connection.id, connection]));
  return connections.map((connection) => {
    const details = detailsById.get(connection.id);
    if (!details)
      return connection;
    const merged = { ...connection };
    for (const [key, value] of Object.entries(details)) {
      if (merged[key] == null) {
        merged[key] = value;
      }
    }
    return merged;
  });
}
function formatConnectionList(connections) {
  return connections.map((conn) => ({
    Id: conn.id,
    Name: conn.name,
    ConnectorKey: conn.connector?.key || conn.connectorKey || "",
    ConnectorName: conn.connector?.name || conn.connectorName || "",
    State: conn.state,
    Owner: conn.owner,
    IsDefault: conn.isDefault ? "Yes" : "No",
    ByoaConnection: conn.byoaConnection === true ? "Yes" : "No",
    ElementInstanceId: conn.elementInstanceId ?? "",
    Folder: conn.folder?.name || conn.folderName || "",
    FolderKey: conn.folder?.key || conn.folderKey || "",
    Created: conn.createTime ? new Date(conn.createTime).toISOString() : "",
    Updated: conn.updateTime ? new Date(conn.updateTime).toISOString() : ""
  }));
}
function buildDisabledWarning(connections) {
  if (connections.length === 0)
    return;
  const disabled = connections.filter((c) => c.state !== "Enabled" && c.state !== "enabled");
  if (disabled.length === connections.length) {
    return "All connections are not enabled. Run 'uip is connections edit <connection-id>' to re-authenticate, or 'uip is connections create <connector-key>' to create a new connection.";
  }
  if (disabled.length > 0) {
    const names = disabled.map((c) => String(c.name || c.id)).join(", ");
    return `Connection(s) not enabled: ${names}. Only Enabled connections can be used for operations. Run 'uip is connections edit <connection-id>' to re-authenticate.`;
  }
  return;
}
function isConnectionEnabled(status) {
  return normalizeConnectionStatus(status) === "Enabled";
}
function extractConnectionDiagnosticText(value) {
  if (typeof value !== "string") {
    return;
  }
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}
function buildConnectionPingFailure(connectionId, status, diagnosticReason) {
  const statusLabel = normalizeConnectionStatus(status);
  const reason = extractConnectionDiagnosticText(diagnosticReason);
  const message = reason ? `Connection '${connectionId}' is not enabled (status: ${statusLabel}). Reason: ${reason}` : `Connection '${connectionId}' is not enabled (status: ${statusLabel}).`;
  if (statusLabel === "Expired") {
    return {
      message,
      instructions: `Run 'uip is connections edit ${connectionId}' to re-authenticate the expired connection.`
    };
  }
  if (!reason) {
    return {
      message,
      instructions: "The Integration Service API did not return a detailed failure reason. Inspect the connection in Automation Cloud, then re-authenticate only if credentials are expired or invalid."
    };
  }
  if (/admin|administrator|consent|policy|authorization|permission|access/i.test(reason)) {
    return {
      message,
      instructions: "Review the reported reason and involve a tenant administrator if consent, policy, or authorization changes are required. Re-authenticate only after the administrative blocker is resolved."
    };
  }
  return {
    message,
    instructions: "Review the reported reason before choosing remediation. Re-authenticate only if the reason indicates expired or invalid credentials."
  };
}

