// src/services/connector-builder/operations/remote.ts
var DEFAULT_SEARCH_LIMIT = 1000;
function isDesignKey(key) {
  return /^design/i.test(key);
}
function isNotLoggedIn(e) {
  const message = e instanceof Error ? e.message : String(e);
  return /not logged in|run ['`]?uip login/i.test(message);
}
function toRemoteError(e) {
  if (isNotLoggedIn(e)) {
    return {
      code: "notLoggedIn",
      message: "Not logged in.",
      fixHint: "Run `uip login` then retry."
    };
  }
  return {
    code: "remoteFailed",
    message: e instanceof Error ? e.message : String(e),
    fixHint: "Check the tenant, connector, and your network, then retry."
  };
}
function scoreConnector(c, qLower, tokens) {
  const key = c.key.toLowerCase();
  const name = (c.name ?? "").toLowerCase();
  const desc = (c.description ?? "").toLowerCase();
  let score = 0;
  if (key === qLower)
    score += 1000;
  else if (key.includes(qLower))
    score += 120;
  if (name === qLower)
    score += 200;
  else if (name.includes(qLower))
    score += 80;
  if (desc.includes(qLower))
    score += 20;
  for (const t of tokens) {
    if (key.includes(t))
      score += 20;
    if (name.includes(t))
      score += 15;
    if (desc.includes(t))
      score += 5;
  }
  return score;
}
async function searchDesignConnectors(options, query, limit = DEFAULT_SEARCH_LIMIT) {
  try {
    const { items, truncated } = await listConnectors(options, {
      limit,
      design: true
    });
    const designs = items.filter((c) => isDesignKey(c.key));
    const qLower = query.trim().toLowerCase();
    const tokens = qLower.split(/\s+/).filter(Boolean);
    const candidates = designs.map((c) => ({ ...c, score: scoreConnector(c, qLower, tokens) })).filter((c) => c.score > 0).sort((a, b) => b.score - a.score).slice(0, 10);
    return {
      ok: true,
      data: { candidates, scanned: designs.length, truncated }
    };
  } catch (e) {
    return { ok: false, error: toRemoteError(e) };
  }
}
async function getConnector(options, params) {
  const include = params.include ?? "metadata";
  const opts = params.tenant !== undefined ? { ...options, tenant: params.tenant } : options;
  if (!params.key) {
    if (!params.query) {
      return {
        ok: false,
        error: {
          code: "invalidArguments",
          message: "Provide 'key' (exact connector key) or 'query' (search text).",
          fixHint: "Pass --key <connectorKey> or --query <text>."
        }
      };
    }
    const search = await searchDesignConnectors(opts, params.query, params.limit);
    if (!search.ok)
      return search;
    return { ok: true, data: { kind: "candidates", ...search.data } };
  }
  let ref;
  try {
    ref = await findDesignConnectorByKey(opts, params.key);
  } catch (e) {
    return { ok: false, error: toRemoteError(e) };
  }
  if (!ref) {
    const search = await searchDesignConnectors(opts, params.key, params.limit);
    if (!search.ok)
      return search;
    return {
      ok: false,
      error: {
        code: "notFound",
        message: `No connector found with key '${params.key}'.`,
        fixHint: search.data.candidates.length > 0 ? "Pick a candidate key from the error and retry, or run a broader --query." : "Check the connector key, or list connectors with --query.",
        candidates: search.data.candidates,
        truncated: search.data.truncated
      }
    };
  }
  try {
    if (include === "files") {
      const bytes = await exportConnectorZip(opts, ref.id);
      const fs3 = getFileSystem();
      const base = params.path ? fs3.path.resolve(params.path) : fs3.env.cwd();
      const { root, key } = await unpackConnectorZip(bytes, base);
      return {
        ok: true,
        data: { kind: "files", id: ref.id, key, root }
      };
    }
    const connector = await getConnectorById(opts, ref.id);
    return { ok: true, data: { kind: "metadata", connector } };
  } catch (e) {
    return { ok: false, error: toRemoteError(e) };
  }
}
async function importConnector(options, params) {
  const opts = params.tenant !== undefined ? { ...options, tenant: params.tenant } : options;
  try {
    const root = await resolveConnectorRoot2(params.path ?? ".");
    await readElementJsonChecked(root);
    const packed = await packConnectorToBytes(root);
    const parsed = await importConnectorZip(opts, packed.bytes, packed.fileName);
    const existing = await findDesignConnectorByKey(opts, parsed.key);
    const persisted = existing ? await updateDesignConnector(opts, existing.id, parsed) : await createDesignConnector(opts, parsed);
    return {
      ok: true,
      data: {
        id: persisted.id,
        key: persisted.key,
        name: persisted.name,
        operation: existing ? "Updated" : "Created"
      }
    };
  } catch (e) {
    return { ok: false, error: toRemoteError(e) };
  }
}

