  const fs3 = getFileSystem();
  const fileExists = await fs3.exists(filePath);
  const fileSnapshot = fileExists ? await fs3.readFile(filePath, "utf-8") : null;
  const snapshot = await readElementJson(root);
  const element = JSON.parse(JSON.stringify(snapshot));
  const referenceRemoved = stripHookReferences(element, filename);
  if (!fileExists && !referenceRemoved) {
    return {
      ok: false,
      error: {
        code: "hookNotFound",
        message: `No hook file or reference found for '${filename}'.`,
        fixHint: "Check the filename (e.g. 'resource-account-GET-postRequest.js' or 'global-preRequest.js')."
      }
    };
  }
