  for (const h of globalHooks) {
    if (typeof h.ref === "string")
      refs.add(h.ref);
  }
  const resources = element.resources ?? [];
  for (const resource of resources) {
    const hooks = resource.hooks;
    if (!hooks)
      continue;
    for (const h of hooks) {
      if (typeof h.ref === "string")
        refs.add(h.ref);
    }
  }
