// src/services/connector-builder/operations/addConfig.ts
async function addConfig(params) {
  const { connectorRoot, entry, forceUpdateExisting = false } = params;
  const element = await readElementJson(connectorRoot);
  const existing = element.configuration?.find((c) => c.key === entry.key);
  if (!existing) {
    upsertConfig(element, entry);
    await writeElementJson(connectorRoot, element);
    return { ok: true, data: { outcome: "added", key: entry.key } };
  }
  const diff = diffConfigEntries(existing, entry);
  if (Object.keys(diff).length === 0) {
    return { ok: true, data: { outcome: "unchanged", key: entry.key } };
  }
  const safeDiff = redactConfigDiff(diff, isSecretConfigEntry(existing) || isSecretConfigEntry(entry));
  if (!forceUpdateExisting) {
    return {
      ok: false,
      error: {
        code: "configConflict",
        message: `Configuration entry '${entry.key}' already exists with different values.`,
        key: entry.key,
        diff: safeDiff,
        fixHint: "Re-run with --force to apply the diff, or change the input so it matches the existing entry.",
        requiredArgs: ["--force"]
      }
    };
  }
  upsertConfig(element, entry);
  await writeElementJson(connectorRoot, element);
  return {
    ok: true,
    data: { outcome: "updated", key: entry.key, diff: safeDiff }
  };
}

// src/data/builder/eventConfigs.ts
function clone2(value) {
  return JSON.parse(JSON.stringify(value));
}
var POLLING_EVENT_CONFIGS = [
  EVENT_NOTIFICATION_ENABLED,
  EVENT_NOTIFICATION_CALLBACK_URL,
  EVENT_VENDOR_TYPE,
  EVENT_POLLER_REFRESH_INTERVAL,
  EVENT_POLLER_CONFIGURATION,
  EVENT_RAW_ENABLED
];
var WEBHOOK_EVENT_CONFIGS = [
  EVENT_NOTIFICATION_ENABLED,
  EVENT_NOTIFICATION_CALLBACK_URL,
  EVENT_NOTIFICATION_CALLBACK_HEADERS,
  EVENT_NOTIFICATION_SIGNATURE_KEY,
  EVENT_NOTIFICATION_BASIC_AUTH_USERNAME,
  EVENT_NOTIFICATION_BASIC_AUTH_PASSWORD,
  EVENT_NOTIFICATION_INSTANCE_FINDER,
  EVENT_VENDOR_TYPE,
  EVENT_RAW_ENABLED
];
var ALL_EVENT_CONFIGS = [
  EVENT_NOTIFICATION_ENABLED,
  EVENT_NOTIFICATION_CALLBACK_URL,
  EVENT_NOTIFICATION_CALLBACK_HEADERS,
  EVENT_NOTIFICATION_SIGNATURE_KEY,
  EVENT_NOTIFICATION_BASIC_AUTH_USERNAME,
  EVENT_NOTIFICATION_BASIC_AUTH_PASSWORD,
  EVENT_NOTIFICATION_INSTANCE_FINDER,
  EVENT_VENDOR_TYPE,
  EVENT_POLLER_REFRESH_INTERVAL,
  EVENT_POLLER_CONFIGURATION,
  EVENT_RAW_ENABLED
];
function getEventConfigs({
  eventType = "polling",
  overrides = null
} = {}) {
  let entries;
  if (eventType === "webhook") {
    entries = clone2(WEBHOOK_EVENT_CONFIGS);
  } else if (eventType === "all") {
    entries = clone2(ALL_EVENT_CONFIGS);
  } else {
    entries = clone2(POLLING_EVENT_CONFIGS);
  }
  if (eventType === "polling") {
    for (const entry of entries) {
      if (entry.key === "event.vendor.type") {
        entry.defaultValue = "polling";
      }
    }
  }
  if (overrides) {
    for (const entry of entries) {
      const override = overrides[entry.key];
      if (override !== undefined) {
        entry.defaultValue = override;
      }
    }
  }
  return entries;
}

// src/services/connector-builder/operations/configPreset.ts
function clone3(value) {
  return JSON.parse(JSON.stringify(value));
}
var PAGINATION_PRESET = [
  PAGINATION_MAX,
  PAGINATION_TYPE,
  PAGINATION,
  PAGINATION_PAGE_START_INDEX
];
var BASE_PRESET = [
  BASE_URL,
  FILTER_RESPONSE_NULLS,
  DEFAULT_SELECT_FIELDS_MAP,
  INSTANCE_VARIABLES,
  CONNECTION_IDENTITY_LOOKUP_KEY
];
function buildPresetEntries(args) {
  const { kind, eventType = "polling", overrides } = args;
  if (kind === "event") {
    return getEventConfigs({ eventType, overrides: overrides ?? null });
  }
  let source;
  if (kind === "pagination") {
    source = PAGINATION_PRESET;
  } else if (kind === "base") {
    source = BASE_PRESET;
  } else {
    return null;
  }
  return source.map((entry) => {
    const copy = clone3(entry);
    const override = overrides?.[copy.key];
    if (override !== undefined) {
      copy.defaultValue = override;
    }
    return copy;
  });
}
async function addConfigPreset(args) {
  const entries = buildPresetEntries(args);
  if (entries === null) {
    return {
      ok: false,
      error: {
        code: "unknownKind",
        message: `Unknown preset kind: '${args.kind}'.`,
        fixHint: "Use one of: pagination, base, event."
      }
    };
  }
  const { connectorRoot, kind, forceUpdateExisting = false } = args;
  const element = await readElementJson(connectorRoot);
  const plan = planConfigChanges(element, entries);
  if (!forceUpdateExisting && plan.toUpdate.length > 0) {
    return {
      ok: false,
      error: {
        code: "configConflict",
        message: `${plan.toUpdate.length} existing configuration entry(ies) would be modified by the '${kind}' preset.`,
        fixHint: "Re-run with --force to apply the diff, or remove the conflicting entries first.",
        conflicts: plan.toUpdate.map((u) => ({
          key: u.key,
          existing: redactConfigEntry(u.existing),
          proposed: redactConfigEntry(u.proposed),
          diff: redactConfigDiff(u.diff, isSecretConfigEntry(u.existing) || isSecretConfigEntry(u.proposed))
        }))
      }
    };
  }
  const added = [];
  const updated = [];
  const unchanged = [...plan.unchanged];
  for (const p of plan.toAdd) {
    upsertConfig(element, p);
    added.push(p.key);
  }
  for (const u of plan.toUpdate) {
    upsertConfig(element, u.proposed);
    updated.push({
      key: u.key,
      diff: redactConfigDiff(u.diff, isSecretConfigEntry(u.existing) || isSecretConfigEntry(u.proposed))
    });
  }
  await writeElementJson(connectorRoot, element);
  return {
    ok: true,
    data: { connectorRoot, kind, added, updated, unchanged }
  };
}

