// src/services/connector-builder/operations/addPollingEvent.ts
var METADATA_REL2 = ["app", "element", "element-metadata.json"];
var SR_REL4 = ["app", "element", "standard-resources"];
var EVENT_TYPE_META = {
  CREATED: {
    displayName: "Record Created",
    description: "Triggers when a new record is created"
  },
  UPDATED: {
    displayName: "Record Updated",
    description: "Triggers when an existing record is updated"
  },
  DELETED: {
    displayName: "Record Deleted",
    description: "Triggers when a record is deleted"
  }
};
var DEFAULT_DATE_FORMAT = "yyyy-MM-dd'T'HH:mm:ss.SSSZ";
var DEFAULT_EVENT_TYPES = ["CREATED", "UPDATED", "DELETED"];
var POLLER_CONFIG_KEY = "event.poller.configuration";
async function readMetadataFile2(connectorRoot) {
  const fs3 = getFileSystem();
  const path2 = fs3.path.join(connectorRoot, ...METADATA_REL2);
  const text = await fs3.readFile(path2, "utf-8");
  if (text === null)
    return null;
  return JSON.parse(text);
}
async function writeMetadataFile2(connectorRoot, data) {
  const fs3 = getFileSystem();
  const path2 = fs3.path.join(connectorRoot, ...METADATA_REL2);
  await fs3.writeFile(path2, `${JSON.stringify(data, null, 2)}
`);
}
async function srExists(connectorRoot, name) {
  const fs3 = getFileSystem();
  return fs3.exists(fs3.path.join(connectorRoot, ...SR_REL4, `${name}.json`));
}
async function resourceSrExists(connectorRoot, resourceName) {
  if (await resolveSrNameByInternalPath(connectorRoot, `/${resourceName}`) !== null) {
    return true;
  }
  return srExists(connectorRoot, resourceName);
}
function findGetResourcePath(element, resourceName) {
  const resources = element.resources ?? [];
  const target = normalizeInternalPath(`/${resourceName}`);
  for (const resource of resources) {
    if (resource.method !== "GET" || typeof resource.path !== "string") {
      continue;
    }
    if (normalizeInternalPath(resource.path) === target) {
      return resource.path;
    }
  }
  for (const resource of resources) {
    if (resource.standardResourceName === resourceName && resource.method === "GET") {
      return typeof resource.path === "string" ? resource.path : "";
    }
  }
  return "";
}
async function addPollingEvent(args) {
  if (!args.updatedDateField) {
    return {
      ok: false,
      error: {
        code: "missingArg",
        message: "updatedDateField is required.",
        fixHint: "Pass --updated-date-field with the vendor's last-modified field (e.g. 'LastModifiedDate').",
        requiredArgs: ["--updated-date-field"]
      }
    };
  }
  const found = await findElementDir(args.connectorRoot);
  if (!found.ok) {
    if (found.error.code === "ambiguous") {
      return {
        ok: false,
        error: {
          code: "connectorAmbiguous",
          message: "Multiple connector directories found under the current path.",
          fixHint: "Pass --connector-dir pointing at the connector you want to edit.",
          candidates: found.error.candidates
        }
      };
    }
    return {
      ok: false,
      error: {
        code: "connectorNotFound",
        message: "Could not find a connector directory at, above, or immediately below the given path.",
        fixHint: "Pass --connector-dir pointing at a directory that contains app/element/element.json, or run from inside the connector tree."
      }
    };
  }
  const root = found.root;
  const resourceName = args.resourceName;
  const resolvedByPath = await resolveSrNameByInternalPath(root, `/${resourceName}`);
  const srFileName = resolvedByPath ?? resourceName;
  if (resolvedByPath === null && !await srExists(root, resourceName)) {
    return {
      ok: false,
      error: {
        code: "resourceNotFound",
        message: `Resource file not found: ${resourceName}.json`,
        fixHint: "Add the resource first (so app/element/standard-resources/<name>.json exists), then configure polling."
      }
    };
  }
  const dateFormat = args.dateFormat || DEFAULT_DATE_FORMAT;
  const eventTypes = args.eventTypes ?? [...DEFAULT_EVENT_TYPES];
  const idField = args.idField || "Id";
  const dateTimezone = args.dateTimezone || "GMT";
  const createdDateField = args.createdDateField || args.updatedDateField;
  const createdDateFormat = args.createdDateFormat || dateFormat;
  const srSnapshot = await readStandardResource(root, srFileName);
  const elementSnapshot = await readElementJson(root);
  const metadataSnapshot = await readMetadataFile2(root);
  try {
    return await runAddPollingEvent({
      root,
      resourceName,
      srFileName,
      updatedDateField: args.updatedDateField,
      createdDateField,
      idField,
      dateFormat,
      createdDateFormat,
      eventTypes,
      pollingUrl: args.pollingUrl ?? "",
      dateTimezone,
      pollingResourceLabel: args.pollingResourceLabel ?? ""
    });
  } catch (e) {
    await writeStandardResource(root, srFileName, srSnapshot);
    await writeElementJson(root, elementSnapshot);
    if (metadataSnapshot !== null) {
      await writeMetadataFile2(root, metadataSnapshot);
    }
    throw e;
  }
}
async function runAddPollingEvent(args) {
  const {
    root,
    resourceName,
    srFileName,
    updatedDateField,
    createdDateField,
    idField,
    dateFormat,
    createdDateFormat,
    eventTypes,
    dateTimezone
  } = args;
  const warnings = [];
  const element = await readElementJson(root);
  let pollingUrl = args.pollingUrl;
  if (!pollingUrl) {
    const resourcePath = findGetResourcePath(element, resourceName);
    if (resourcePath) {
      const dateExpr = dateTimezone === "GMT" ? `\${gmtDate:${dateFormat}}` : `\${dateTimeZone:${dateTimezone}:${dateFormat}}`;
      pollingUrl = `${resourcePath}?where=${updatedDateField}>'${dateExpr}'`;
    }
  }
  if (!pollingUrl) {
    return {
      ok: false,
      error: {
        code: "pollingUrlUnresolved",
        message: `Could not determine a polling URL for '${resourceName}'. No GET resource entry was found in element.json and no pollingUrl was provided.`,
        fixHint: "Add a GET resource for this standard resource to element.json first, or pass --polling-url explicitly."
      }
    };
  }
  const datesConfiguration = {
    updatedDateField,
    updatedDateFormat: dateFormat,
    createdDateField,
    createdDateFormat
  };
  if (dateTimezone) {
    datesConfiguration.updatedDateTimezone = dateTimezone;
    datesConfiguration.createdDateTimezone = dateTimezone;
  }
  const eventTypeEntries = eventTypes.map((op) => ({
    operation: op,
    ...EVENT_TYPE_META[op] ?? {
      displayName: `Record ${op.charAt(0)}${op.slice(1).toLowerCase()}`,
      description: `Triggers on ${op.toLowerCase()}`
    }
  }));
  const resource = await readStandardResource(root, srFileName);
  setSrMetadataKey(resource, "events", {
    eventMode: ["polling"],
    polling: {
      configuration: {
        datesConfiguration,
        idField,
        url: pollingUrl,
        useLastPollDate: true
      },
      eventTypes: eventTypeEntries
    }
  });
  await writeStandardResource(root, srFileName, resource);
  const pollerKey = resourceName.replaceAll("::", "_").replaceAll("/", "_");
  const configuration = element.configuration ?? [];
  const pollerEntry = configuration.find((c) => c.key === POLLER_CONFIG_KEY);
  let pollerConfigFound = false;
  if (pollerEntry) {
    let pollerConfig = {};
    const raw = pollerEntry.defaultValue ?? "{}";
    try {
      pollerConfig = raw.trim() ? JSON.parse(raw) : {};
    } catch {
      pollerConfig = {};
    }
    pollerConfig[pollerKey] = {
      url: pollingUrl,
      idField,
      datesConfiguration
    };
    pollerEntry.defaultValue = JSON.stringify(pollerConfig);
    pollerConfigFound = true;
  } else {
    warnings.push(`Config entry '${POLLER_CONFIG_KEY}' not found — the per-resource poller config was not written. Run the event/polling preset first (it adds the poller config entry), then re-run this command.`);
  }
  const elemMeta = element.elementMetadata ?? {};
  const currentEventTypes = elemMeta.eventTypes ?? [];
  if (!currentEventTypes.includes("polling")) {
    currentEventTypes.push("polling");
  }
  elemMeta.eventTypes = currentEventTypes;
  const existingPollingResources = elemMeta.pollingResources;
  const label = args.pollingResourceLabel || (existingPollingResources === undefined ? "events" : resourceName);
  const pollingResources = existingPollingResources ?? [];
  if (!pollingResources.includes(label)) {
    pollingResources.push(label);
  }
  elemMeta.pollingResources = pollingResources;
  element.elementMetadata = elemMeta;
  await writeElementJson(root, element);
  const metadata = await readMetadataFile2(root);
  if (metadata !== null && metadata.hasEvents !== true) {
    metadata.hasEvents = true;
    await writeMetadataFile2(root, metadata);
  }
  return {
    ok: true,
    data: {
      connectorRoot: root,
      resourceName,
      eventTypes,
      pollingUrl,
      pollerConfigKey: pollerConfigFound ? pollerKey : "",
      pollingConfig: {
        updatedDateField,
        createdDateField,
        idField,
        dateFormat,
        timezone: dateTimezone
      },
      warnings
    }
  };
}

