// src/helpers/typecache.ts
async function getAuthContext2(tenant) {
  const status = await getLoginStatusAsync();
  if (status.loginStatus !== "Logged in" || !status.accessToken || !status.baseUrl || !status.organizationId || !status.tenantId) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const tenantId = await resolveTenantId(tenant);
  return {
    baseUrl: status.baseUrl,
    organizationId: status.organizationId,
    tenantId,
    accessToken: status.accessToken
  };
}
function commonParams(projectType) {
  return [
    ["useLucene", "true"],
    ["useElastic", "true"],
    ["useSvgUrl", "true"],
    ["includeVirtualPackages", "true"],
    ["boostPackages", "UiPath.System.Activities"],
    ["boostPackages", "UiPath.WebAPI.Activities"],
    ["targetPlatforms", "CrossPlatform"],
    ["projectType", projectType]
  ];
}
function buildPackagesUrl(ctx, projectType) {
  const params = new URLSearchParams([
    ["withActivities", "true"],
    ["withTriggers", "false"],
    ["useLatestPackages", "true"],
    ...commonParams(projectType)
  ]);
  return `${ctx.baseUrl}/${ctx.organizationId}/studio_/typecache/api/Packages?${params}`;
}
function buildActivitiesUrl(ctx, packageId, projectType) {
  const params = new URLSearchParams(commonParams(projectType));
  return `${ctx.baseUrl}/${ctx.organizationId}/studio_/typecache/api/Activities/Package/${packageId}?${params}`;
}
function buildHeaders(ctx) {
  return {
    Authorization: `Bearer ${ctx.accessToken}`,
    Accept: "application/json",
    "X-UiPath-TenantGlobalId": ctx.tenantId,
    "X-UiPath-TenantId": ctx.tenantId,
    "X-UiPath-Internal-TenantId": ctx.tenantId
  };
}
async function fetchTypecachePackages(projectType, tenant) {
  const ctx = await getAuthContext2(tenant);
  const response = await fetch(buildPackagesUrl(ctx, projectType), {
    headers: buildHeaders(ctx)
  });
  if (!response.ok) {
    throw new Error(`Typecache packages fetch failed: ${response.status} ${response.statusText}`);
  }
  const packages = await response.json();
  return packages.map((p) => ({
    packageId: p.id,
    key: p.connectorKey,
    name: p.displayName
  }));
}
async function fetchTypecacheActivities(packageId, projectType, tenant) {
  const ctx = await getAuthContext2(tenant);
  const response = await fetch(buildActivitiesUrl(ctx, packageId, projectType), { headers: buildHeaders(ctx) });
  if (!response.ok) {
    throw new Error(`Typecache activities fetch failed: ${response.status} ${response.statusText}`);
  }
  const raw = await response.json();
  return raw.flatMap((a) => {
    let config = null;
    try {
      config = JSON.parse(a.configuration);
    } catch {
      return [];
    }
    if (!config.objectName)
      return [];
    return [
      {
        displayName: a.displayName,
        description: a.description,
        objectName: config.objectName,
        methodName: config.httpMethod ?? "",
        operation: config.operation ?? undefined,
        connectorKey: config.connectorKey
      }
    ];
  });
}
function formatTypecacheConnectorList(connectors) {
  return connectors.map((c) => ({
    Key: c.key,
    Name: c.name
  }));
}
function formatTypecacheActivityList(activities) {
  return activities.map((a) => ({
    DisplayName: a.displayName,
    Description: a.description || "N/A",
    ObjectName: a.objectName,
    MethodName: a.methodName || "N/A",
    Operation: a.operation || "N/A"
  }));
}

