var registerTypecacheCommand = (program2) => {
  const typecache = program2.command("typecache").description("Fetch connectors and activities from the Studio typecache");
  typecache.command("packages").description("List connectors available to a project type").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--refresh", "Force re-fetch from API, ignoring cache").option("--project-type <type>", "Project type to query (e.g. Agent)", "Agent").examples(PACKAGES_EXAMPLES).trackedAction(processContext, async (options) => {
    logger.info(`Listing typecache packages for project type ${options.projectType}${options.refresh ? " [refresh]" : ""}`);
    let data = null;
    if (!options.refresh) {
      data = await readTypecachePackages(options.projectType, options.tenant);
      if (data)
        logger.info(`Loaded ${data.length} typecache packages from cache`);
    }
    if (!data) {
      const [fetchError, fetched] = await catchError(fetchTypecachePackages(options.projectType, options.tenant));
      if (fetchError) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Error listing typecache packages",
          Instructions: fetchError.message
        });
        processContext.exit(1);
        return;
      }
      data = fetched;
      if (data.length > 0)
        await writeTypecachePackages(options.projectType, data, options.tenant);
    }
    OutputFormatter.emitList("ConnectorList", formatTypecacheConnectorList(data ?? []), {
      emptyInstructions: `No connectors found for project type '${options.projectType}'.`
    });
  });
  typecache.command("activities").description("List activities for a connector for a project type").argument("<connector-key>", "Connector key (e.g., uipath-zoho-desk)").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--refresh", "Force re-fetch from API, ignoring cache").option("--project-type <type>", "Project type to query (e.g. Agent)", "Agent").examples(ACTIVITIES_EXAMPLES).trackedAction(processContext, async (connectorKey, options) => {
    logger.info(`Listing typecache activities for ${connectorKey} (project type ${options.projectType})${options.refresh ? " [refresh]" : ""}`);
    let activities = null;
    if (!options.refresh) {
      activities = await readTypecacheActivities(options.projectType, connectorKey, options.tenant);
      if (activities)
        logger.info(`Loaded ${activities.length} typecache activities from cache`);
    }
    if (!activities) {
      let packages = null;
      if (!options.refresh) {
        packages = await readTypecachePackages(options.projectType, options.tenant);
      }
      if (!packages) {
        const [connErr, fetched2] = await catchError(fetchTypecachePackages(options.projectType, options.tenant));
        if (connErr) {
          OutputFormatter.error({
            Result: RESULTS.Failure,
            Message: "Error fetching typecache package list",
            Instructions: connErr.message
          });
          processContext.exit(1);
          return;
        }
        packages = fetched2;
        if (packages.length > 0)
          await writeTypecachePackages(options.projectType, packages, options.tenant);
      }
      const pkg = packages.find((p) => p.key.toLowerCase() === connectorKey.toLowerCase());
      if (!pkg) {
        OutputFormatter.emitList("ActivityList", [], {
          emptyInstructions: `Connector '${connectorKey}' is not available for project type '${options.projectType}'. Run 'uip is typecache packages --project-type ${options.projectType}' to see available connectors.`
        });
        return;
      }
      const packageId = pkg.packageId;
      const [actErr, fetched] = await catchError(fetchTypecacheActivities(packageId, options.projectType, options.tenant));
      if (actErr) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: `Error fetching activities for connector '${connectorKey}'`,
          Instructions: actErr.message
        });
        processContext.exit(1);
        return;
      }
      activities = fetched;
      if (activities.length > 0)
        await writeTypecacheActivities(options.projectType, connectorKey, activities, options.tenant);
    }
    OutputFormatter.emitList("ActivityList", formatTypecacheActivityList(activities ?? []), {
      emptyInstructions: `No activities found for connector '${connectorKey}' for project type '${options.projectType}'.`
    });
  });
};

